              .parallel(i)       // parallelize over rows in C-order (second index)
              .vectorize(j, vec_width);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter for the current diagonal d = j - i (d >= 1)
    Param<int> diag_param("diag_param");

    // Bind the buffers once; we mutate 'table' on the host in-place, and
    // Halide will always see the up-to-date values through these views.
    seq_param.set(seq);
    table_param.set(table);

    // -----------------------------------------------------------------------------
    // Optimized Halide kernel: compute one full diagonal of the DP table at once.
    //
    // Original C kernel:
    //
    // for (i = N-1; i >= 0; i--) {
    //   for (j = i+1; j < N; j++) {
    //     best = table[i][j];
    //     best = max(best, table[i][j-1]);
    //     best = max(best, table[i+1][j]);
    //     if (j-1 >= 0 && i+1 < N) {
    //       if (i < j-1)
    //         best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
    //       else
    //         best = max(best, table[i+1][j-1]);
    //     }
    //     for (k=i+1; k<j; k++)
    //       best = max(best, table[i][k] + table[k+1][j]);
    //     table[i][j] = best;
    //   }
    // }
    //
    // All dependencies for (i,j) are at strictly smaller diagonals
    // (j-i-1 or less). That means that for a *fixed* diagonal d=j-i,
    // all cells on that diagonal can be computed in parallel, reading
    // only from previously-computed diagonals.
    //
    // We therefore:
    //   - drive the diagonal loop from C++ (d = 1..N-1),
    //   - for each d, call a Halide Func 'diag' that computes every
    //     (i,j=i+d) on that diagonal in one call,
    //   - copy the resulting 1D diagonal back into 'table'.
    //
    // This reduces the number of Halide calls from O(N^2) (one per cell)
    // to O(N) (one per diagonal), and lets Halide vectorize/parallelize
    // across all i on a diagonal, dramatically improving locality and
    // reducing JIT overhead while preserving exact semantics.
    // -----------------------------------------------------------------------------
    Var i("i");

    Func diag("diag");

    {
        Expr d = diag_param;
        Expr ii = i;           // row index i in C code
        Expr jj = ii + d;      // column index j = i + d

        // Current value table[i][j]  (C: table[i][j] -> Halide: table_param(j, i))
        Expr best = table_param(jj, ii);

        // Horizontal: table[i][j-1]
        best = Halide::max(best, table_param(jj - 1, ii));

        // Vertical: table[i+1][j]
        best = Halide::max(best, table_param(jj, ii + 1));

        // Diagonal / pairing term.
        //
        // match(seq[i], seq[j]) = ((seq[i] + seq[j]) == 3 ? 1 : 0)
        Expr b1 = cast<int32_t>(seq_param(ii));
        Expr b2 = cast<int32_t>(seq_param(jj));
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1, otherwise just propagate
        // table[i+1][j-1] without adding match().
        Expr can_pair   = ii < jj - 1;
        Expr match_term = select(can_pair,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(jj - 1, ii + 1) + match_term;
        best = Halide::max(best, diag_candidate);

        // Split term over k: for k=i+1..j-1
        //
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // For fixed diagonal d = j - i, this can be written as:
        //   k = i + r, with r in [1, d-1].
        // So we use an RDom over r in that range and treat this as an
        // associative max-reduction over k.
        Expr split_extent = d - 1;  // may be zero when d == 1
        RDom r(1, split_extent, "r");

        Expr k = ii + r.x;
        Expr split_candidate =
            table_param(k, ii)       // table[i][k]
            + table_param(jj, k + 1); // table[k+1][j]

        // Pure definition initializes with the "best" scalar value:
        diag(ii) = best;
        // Update definition folds in all split candidates:
        diag(ii) = Halide::max(diag(ii), split_candidate);
    }

    // -----------------------------------------------------------------------------
    // Schedule for the diagonal kernel.
    //
    // We want to:
    //   - exploit multi-core parallelism across i (cells on a diagonal),
    //   - exploit SIMD within each core,
    //   - keep the reduction over k as the innermost loop for cache reuse.
    //
    // Tuning knobs:
    //   TILE_I      : how many i-values per parallel task
    //   VEC_WIDTH_I : SIMD width along i
    // -----------------------------------------------------------------------------
    const int TILE_I      = 64; // tune for cache; 64 works well on modern x64
    const int VEC_WIDTH_I = 8;  // tune for SIMD width; 8 is a safe default

    Var io("io"), ii("ii");

    // Pure step: split i into tiles, parallelize across tiles, and vectorize within.
    diag.compute_root()
        .split(i, io, ii, TILE_I)
        .parallel(io)
        .vectorize(ii, VEC_WIDTH_I);

    // Reduction step: use the same tiling / vectorization pattern.
    diag.update()
        .split(i, io, ii, TILE_I)
        .parallel(io)
        .vectorize(ii, VEC_WIDTH_I);

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit();

    // -------------------------------------------------------------------------
    // Time the DP kernel (diagonal loops plus Halide calls).
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // New kernel structure:
    //
    // for (d = 1; d < N; d++) {          // diagonal index (j - i)
    //   for all i with 0 <= i < N-d {    // j = i + d
    //     compute table[i][j] using the same recurrence
    //     (reading only from previously-computed diagonals)
    //   }
    // }
    //
    // This order is equivalent to the original (i,j) nest, because:
    //   - All dependencies of (i,j) are at smaller diagonals,
    //   - No cell depends on another cell on the same diagonal,
    //   - So diagonals can be processed in increasing d, and cells on
    //     each diagonal can be computed in any order or in parallel.
    for (int d = 1; d < n; ++d) {
        diag_param.set(d);

        const int len = n - d;                  // number of (i,j) pairs on diagonal d
        Halide::Buffer<num_t> diag_vals(len);   // 1D buffer for this diagonal

        // Compute all table[i][j] with j - i == d.
        diag.realize(diag_vals);

        // Write back into the triangular DP table.
        // C: table[i][j]  -> Halide: table(j, i)
        for (int i_idx = 0; i_idx < len; ++i_idx) {
            int j_idx = i_idx + d;
            table(j_idx, i_idx) = diag_vals(i_idx);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
