#include "nussinov.hpp"

using num_t  = DATA_TYPE;   // type used for table entries
using base_t = uint8_t;     // type used for RNA bases (0..3)

using namespace Halide;

// Simple tuning knobs for the Halide schedules.
// You can change these to better match a given CPU.
static constexpr int VEC_WIDTH = 8;   // vector width along the main loop
static constexpr int TILE_I    = 64;  // tile size along i for parallelism

// Initialize seq and table as in the original C code.
static void init_array(int n,
                       Halide::Buffer<base_t, 1> seq,
                       Halide::Buffer<num_t, 2> table) {
    Var i("i"), j("j");

    Func init_seq("init_seq"), init_table("init_table");

    // base is AGCT/0..3
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // table[i][j] = 0 for all i,j
    // Remember: C uses table[i][j]; we map that to table(j, i).
    init_table(j, i) = cast<num_t>(0);

    // A tiny bit of scheduling to make initialization reasonably fast.
    init_seq
        .compute_root()
        .vectorize(i, VEC_WIDTH);
    init_table
        .compute_root()
        .parallel(i)
        .vectorize(j, VEC_WIDTH);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter: current diagonal length l = j - i (> 0)
    Param<int> l_param("l");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // --------------------------------------------------------------------
    // Optimized dynamic-programming kernel
    //
    // The original C kernel:
    //
    //   for (i = N-1; i >= 0; i--) {
    //     for (j = i+1; j < N; j++) {
    //       best = table[i][j];
    //       best = max(best, table[i][j-1]);
    //       best = max(best, table[i+1][j]);
    //       best = max(best, table[i+1][j-1] + match(i,j) or table[i+1][j-1]);
    //       for (k = i+1; k < j; k++)
    //         best = max(best, table[i][k] + table[k+1][j]);
    //       table[i][j] = best;
    //     }
    //   }
    //
    // This order is one valid topological traversal of the DAG of
    // dependencies (each (i,j) depends only on entries (i',j') with
    // i' > i or j' < j). Any order that respects these dependencies
    // produces the same final table.
    //
    // For performance, we instead iterate by *diagonals* of constant
    // length l = j - i:
    //
    //   for (l = 1; l < N; l++) {
    //     for (i = 0; i < N-l; i++) {
    //       j = i + l;
    //       ...same recurrence using only smaller diagonals...
    //     }
    //   }
    //
    // For fixed l, all references in the recurrence go to entries on
    // strictly smaller diagonals (j-i < l), so all cells on a single
    // diagonal are independent and can be computed in parallel.
    //
    // We express the update of an entire diagonal as a 1D Halide Func
    // over i, parameterized by l_param. The DP table is treated as a
    // read-only ImageParam inside this Func; we then write the
    // results back to 'table' on the host.
    // --------------------------------------------------------------------

    Func diag("diag");  // diag(i) corresponds to table[i][i + l_param]
    Var  i("i");

    {
        Expr l = l_param;

        // i in [0, n-l-1], j = i + l
        Expr ie = cast<int>(i);
        Expr je = ie + l;

        // Current value table[i][j]. In the original code this is 0 at
        // first use, but we mirror the C recurrence, which starts from
        // the existing table[i][j].
        Expr best = table_param(je, ie);

        // best = max(best, table[i][j-1]);
        best = max(best, table_param(je - 1, ie));

        // best = max(best, table[i+1][j]);
        best = max(best, table_param(je, ie + 1));

        // Diagonal / pairing term:
        //
        // if (i < j-1)
        //   best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        // else
        //   best = max(best, table[i+1][j-1]);
        //
        Expr b1 = cast<int32_t>(seq_param(ie));
        Expr b2 = cast<int32_t>(seq_param(je));
        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1; otherwise, don't add match().
        Expr match_term = select(ie < je - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(je - 1, ie + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // For fixed l, k runs over an interval of length (l-1).
        // We'll express this as a reduction in r.x, with
        // k = i + 1 + r.x,  r.x in [0, l-2] => extent (l-1).
        //
        // When l == 1, the extent is zero and this update is skipped.
        RDom r(0, l - 1, "r");  // r.x = 0..l-2

        diag(i) = best;  // pure definition

        // Reduction update: take the maximum over k.
        Expr k = ie + 1 + r.x;
        diag(i) = max(diag(i),
                      table_param(k, ie) + table_param(je, k + 1));
    }

    // --------------------------------------------------------------------
    // Schedule for the diagonal kernel.
    //
    // We compute each diagonal as a 1D vector of length ~N, and:
    //  - tile along i for cache locality and parallelism
    //  - vectorize within each tile
    //
    // The tile size and vector width are controlled by the constants
    // TILE_I and VEC_WIDTH at the top of the file.
    // --------------------------------------------------------------------
    Var io("io"), ii("ii");
    diag
        .compute_root()
        .split(i, io, ii, TILE_I)
        .parallel(io)
        .vectorize(ii, VEC_WIDTH);

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit();

    // Time the DP kernel (the l/i loops plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Diagonal-order DP:
    //
    // for (l = 1; l < N; l++) {
    //   for (i = 0; i < N-l; i++) {
    //     j = i + l;
    //     table[i][j] = DP recurrence using only previously computed
    //                   diagonals.
    //   }
    // }
    //
    // This traversal respects all dependencies of the original row-wise
    // order, so the final table is identical, but we can now:
    //  - evaluate an entire diagonal with a single Halide call
    //  - exploit SIMD and multi-core parallelism across i
    for (int l = 1; l < n; ++l) {
        l_param.set(l);

        int len = n - l;  // number of (i,j) pairs on this diagonal

        // diag is a one-dimensional Func over i in [0, len-1].
        Halide::Buffer<num_t> diag_buf = diag.realize({len});

        // Write the diagonal back into the DP table.
        // C: table[i][j]  -> Halide: table(j, i)
        for (int i = 0; i < len; ++i) {
            int j = i + l;
            table(j, i) = diag_buf(i);
        }

        // We have updated the host memory of 'table'; the ImageParam
        // holds a reference to the same Buffer object, so future
        // realizations of 'diag' will see the updated values.
        // (No need to call set() again.)
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
