        // initialized to 0 before any updates, and then only max()
        // with non-negative candidates is applied, so taking 0 as the
        // initial "best" is equivalent to starting from table[i][j].
        Expr best = cast<num_t>(Expr(0));

        // Neighbor terms: table[i][j-1], table[i+1][j]
        // Mapping: table[i][j] -> table_param(j, i)
        best = max(best, table_param(j - 1, i));     // table[i][j-1]
        best = max(best, table_param(j, i + 1));     // table[i+1][j]

        // Diagonal / pairing term:
        //
        // if (i < j-1)
        //   best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        // else
        //   best = max(best, table[i+1][j-1]);
        //
        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
