        // Only allow bonding when i < j-1 (minimum separation of 1 base).
        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(Expr(0)));

        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // For fixed diagonal d = j - i, k ranges over (i+1..j-1).
        // All dependencies are on smaller diagonals, so cells on
        // the same diagonal are independent.
        //
        // Express this as a reduction over r in [0, d-1):
        //   k = i + 1 + r
        Expr split_extent = max(d - 1, 0);   // d >= 1 in our host loop, but
                                             // guard for safety (extent >= 0).
        RDom r(0, split_extent, "r");

        diag_update(idx) = best;

        Expr k = i + 1 + r.x;
        diag_update(idx) = max(diag_update(idx),
                               table_param(k, i) + table_param(j, k + 1));
    }

    // ---------------------- Scheduling for diag_update -----------------
    // We want to exploit parallelism and SIMD along the diagonal index
    // 'idx'. The reduction in 'r' has loop-carried dependencies and
    // remains serial per element, but different elements of the
    // diagonal are independent.
    //
    // We:
    //   * compute the Func at root
    //   * tile 'idx' into [outer, inner]
    //   * parallelize across tiles
    //   * vectorize across the inner portion
    //
