    // element type (num_t). The tile size (here 64) is a tunable
    // constant that balances parallel overhead vs work per tile.
    Target target = get_jit_target_from_environment();
    const Type num_type = type_of<num_t>();
    const int vec_width = target.natural_vector_size(num_type);
    const int tile_size = 64;

    Var idx_outer("idx_outer"), idx_inner("idx_inner");

    diag_update
        .compute_root()
        .split(idx, idx_outer, idx_inner, tile_size)
        .parallel(idx_outer)
        .vectorize(idx_inner, vec_width);

    diag_update.update()
        .split(idx, idx_outer, idx_inner, tile_size)
        .parallel(idx_outer)
        .vectorize(idx_inner, vec_width);

    // JIT-compile the per-diagonal pipeline once.
    diag_update.compile_jit(target);

    // Workspace buffer to hold one diagonal. We'll reuse it for all
    // diagonals via cropping to avoid per-diagonal allocations.
    Halide::Buffer<num_t> diag_workspace(n);

    // Time the DP kernel (the diagonal loops plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Diagonal-order dynamic program:
    //
    // for (d = 1; d < N; d++) {
    //   for (i = 0; i < N-d; i++) {
    //     j = i + d;
    //     ... compute table[i][j] ...
    //   }
    // }
    //
    // This is equivalent to the original (i,j) order because every
    // dependency for (i,j) is on cells with strictly smaller d = j-i.
    for (int d = 1; d < n; ++d) {
        diag_param.set(d);
        int diag_len = n - d;  // number of (i,j) pairs on this diagonal

        // Use a cropped view of the workspace as the realization target
        // to avoid reallocating memory each diagonal.
        Halide::Buffer<num_t> diag_vals = diag_workspace.cropped(0, 0, diag_len);

        // Compute all cells on diagonal d in one Halide call.
        diag_update.realize(diag_vals);

        // Write results back into the DP table.
        for (int i = 0; i < diag_len; ++i) {
            int j = i + d;
            // table[i][j] -> table(j, i)
            table(j, i) = diag_vals(i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
